+// parityKeys renders each entry of a result collection as one summary
+// string via f, so two seams' collections compare as ordered sequences.
+func parityKeys[T any](in []T, f func(T) string) []string {
+	out := make([]string, len(in))
+	for i, v := range in {
+		out[i] = f(v)
+	}
+	return out
+}
+
+// outcomeKey and coreOutcomeKey summarize one per-position evaluation from
+// each seam independently (coreOutcomeKey reads the internal shape
+// directly, not through fromPositionEvaluation): equal sequences mean the
+// facade's result mapping preserved the semantic content.
+func outcomeKey(o PositionOutcome) string {
+	return fmt.Sprintf("%s|%s|%s|%g|%g|%g|%t|%s|%t|%t|%t|%s",
+		o.PositionID, o.RuleID, o.FormulaKey, o.Requirement, o.AppliedProceeds,
+		o.CashCall, o.Permitted, o.DepositKind, o.NoRule, o.Violation,
+		o.MispairedGrouping, o.Error)
+}
+
+func coreOutcomeKey(e account.PositionEvaluation) string {
+	errMsg, mispaired := "", false
+	if e.Error != nil {
+		errMsg = e.Error.Error()
+		mispaired = errors.Is(e.Error, engine.ErrMispairedGrouping)
+	}
+	return fmt.Sprintf("%s|%s|%s|%g|%g|%g|%t|%s|%t|%t|%t|%s",
+		e.PositionID, e.Result.RuleID, e.Result.FormulaKey, e.Result.Requirement,
+		e.Result.AppliedProceeds, e.Result.CashCall, e.Result.Permitted,
+		e.Result.DepositKind, e.NoRule, e.Violation, mispaired, errMsg)
+}
+
+func exclusionKey(e Exclusion) string {
+	return e.PositionID + "|" + string(e.Kind) + "|" + e.Detail
+}
+
+func coreExclusionKey(e account.Exclusion) string {
+	detail := ""
+	if e.Cause != nil {
+		detail = e.Cause.Error()
+	}
+	return e.PositionID + "|" + string(e.Kind) + "|" + detail
+}
