+		o.ID, o.Scope, o.Key, o.Mode, o.Basis, o.Pct, o.Amount, o.Priority, o.Reason,
+		o.ValidFrom.UTC().Format(time.RFC3339Nano), o.ValidTo.UTC().Format(time.RFC3339Nano),
+		o.TxnTime.UTC().Format(time.RFC3339Nano), o.Version)
