+func fixtureRefdata(rows []SecurityFacts) overlay.ReferenceData {
+	if len(rows) == 0 {
+		return overlay.ReferenceData{}
+	}
+	secs := make(map[overlay.SecKey]overlay.SecurityFacts, len(rows))
+	for _, r := range rows {
+		secs[overlay.SecKey{Symbol: r.Symbol, Venue: r.Venue}] = overlay.SecurityFacts{
+			Symbol:          r.Symbol,
+			Venue:           r.Venue,
+			InstrumentKind:  r.InstrumentKind,
+			Underlying:      r.Underlying,
+			IssuerID:        r.IssuerID,
+			Sector:          r.Sector,
+			Industry:        r.Industry,
+			GICSSubIndustry: r.GICSSubIndustry,
+
+			LastPrice:         r.LastPrice,
+			ADV20:             r.ADV20,
+			MedianVolume20:    r.MedianVolume20,
+			MarketCap:         r.MarketCap,
+			SharesOutstanding: r.SharesOutstanding,
+
+			Volatility30D:   r.Volatility30D,
+			HardToBorrow:    r.HardToBorrow,
+			BorrowRate:      r.BorrowRate,
+			Marginable:      r.Marginable,
+			LeveragedFactor: r.LeveragedFactor,
+		}
+	}
+	return overlay.ReferenceData{Securities: secs}
+}
