+// Deliberate-drift canary: Path B evaluated at a shifted AsOf must change
+// the content-addressed TraceID (AsOf participates in accountTraceID as
+// RFC3339Nano), and the suite's own comparison — parityDrift, the exact
+// function assertParity runs — must report it. Proves the suite would
+// actually catch temporal/mapping drift rather than passing vacuously.
+func TestCorpusParity_DriftCanary(t *testing.T) {
+	c := newBaselineClient(t)
+	sdkRes, err := c.Calculate(context.Background(), coveredCallRequest(ModeBaselineOnly))
+	if err != nil {
+		t.Fatalf("SDK Calculate: %v", err)
+	}
+	input := directInput(t, coveredCallRequest(ModeBaselineOnly), fixedNow)
+	input.AsOf = fixedNow.Add(time.Hour)
+	coreRes, err := parityCalculator(t).Calculate(context.Background(), input)
+	if err != nil {
+		t.Fatalf("sdkcore Calculate: %v", err)
+	}
+	drift := parityDrift(sdkRes, coreRes)
+	if !slices.ContainsFunc(drift, func(d string) bool { return strings.HasPrefix(d, "TraceID drift") }) {
+		t.Fatalf("parityDrift under a shifted AsOf reported %v — the suite could not detect temporal drift", drift)
+	}
+}
