+// directInput replicates Client.buildInput's orchestration — mode
+// defaulting, decompose flag, single-sample clock-defaulting of the
+// bitemporal coordinates — over the independent fixture constructions
+// above. Shared by the corpus suite, the drift canary, and
+// TestMappingParity_SDKMatchesSdkcoreDirect.
+func directInput(t *testing.T, req CalculationRequest, now time.Time) sdkcore.Input {
+	t.Helper()
+	mode := req.Mode
+	if mode == "" {
+		mode = ModeHouse
+	}
+	asOf, txnCutoff := req.Snapshot.AsOf, req.Snapshot.TxnCutoff
+	if asOf.IsZero() {
+		asOf = now
+	}
+	if txnCutoff.IsZero() {
+		txnCutoff = now
+	}
+	return sdkcore.Input{
+		Account:           fixtureAccount(req.Snapshot, asOf),
+		Refdata:           fixtureRefdata(req.Snapshot.Refdata),
+		Policy:            fixturePolicyFacts(req.Snapshot.Policy),
+		AsOf:              asOf,
+		TxnCutoff:         txnCutoff,
+		ApplyHouseOverlay: mode == ModeHouse,
+		Decompose:         req.Decompose,
+	}
+}
