+// staticOverrideStore is Path B's independent counterpart to a facade
+// OverrideResolver: it hands the pipeline a fixed internal override set,
+// built without going through toOverride.
+type staticOverrideStore struct {
+	noOverridesStore
+	rows []overlay.Override
+}
+
+func (s staticOverrideStore) Resolve(context.Context, overlay.ResolveQuery) ([]overlay.Override, error) {
+	return s.rows, nil
+}
