+// --- independent fixture→internal construction ------------------------------
+//
+// Path B builds the internal input types straight from the public snapshot
+// WITHOUT calling the facade's production mappers (toAccount,
+// toReferenceData, toPolicyFacts). The duplication is the point: two
+// independent constructions must agree, so a field dropped or miscopied by
+// a facade mapper surfaces as parity drift (seals, totals, TraceID)
+// instead of cancelling out on both paths (PR #297 review).
+
+func fixtureLegs(in []Leg) []engine.Leg {
+	out := make([]engine.Leg, len(in))
+	for i, l := range in {
+		out[i] = engine.Leg{
+			Side:                   engine.Side(l.Side),
+			Kind:                   engine.Kind(l.Kind),
+			OptionType:             l.OptionType,
+			K:                      l.K,
+			P:                      l.P,
+			P0:                     l.P0,
+			Qty:                    l.Qty,
+			Mult:                   l.Mult,
+			Style:                  l.Style,
+			Venue:                  l.Venue,
+			SettleStyle:            l.SettleStyle,
+			Expiration:             l.Expiration,
+			Underlying:             l.Underlying,
+			TimeToExpirationMonths: l.TimeToExpirationMonths,
+			BrokerGuaranteed:       l.BrokerGuaranteed,
+			Shares:                 l.Shares,
+			ShortSaleProceeds:      l.ShortSaleProceeds,
+			SalePrice:              l.SalePrice,
+			Price:                  l.Price,
+			TracksIndex:            l.TracksIndex,
+			Leveraged:              l.Leveraged,
+			TrackingRatio:          l.TrackingRatio,
+			KEquivalent:            l.KEquivalent,
+		}
+	}
+	return out
+}
