+func fixtureAccount(snap CalculationSnapshot, asOf time.Time) account.Account {
+	acctType := snap.Account.Type
+	if acctType == "" {
+		acctType = MarginAccount
+	}
+	phase := snap.Account.Phase
+	if phase == "" {
+		phase = Initial
+	}
+	positions := make([]account.AccountPosition, len(snap.Positions))
+	for i, p := range snap.Positions {
+		positions[i] = account.AccountPosition{
+			ID: p.ID,
+			Position: engine.Position{
+				Legs:                    fixtureLegs(p.Legs),
+				U:                       p.U,
+				Class:                   p.Class,
+				Lev:                     p.Lev,
+				UnderlyingIsEquityBased: p.UnderlyingIsEquityBased,
+			},
+		}
+	}
+	return account.Account{
+		ID:                  snap.Account.ID,
+		AccountType:         engine.AccountType(acctType),
+		Phase:               engine.Phase(phase),
+		AsOf:                asOf,
+		Currency:            snap.Account.Currency,
+		SODEquity:           snap.Bookkeeping.SODEquity,
+		CashBalance:         snap.Bookkeeping.CashBalance,
+		PnL:                 snap.Bookkeeping.PnL,
+		DepositsWithdrawals: snap.Bookkeeping.DepositsWithdrawals,
+		Positions:           positions,
+	}
+}
