+// parityKeys renders each entry of a result collection as one summary
+// string via f, so two seams' collections compare as ordered sequences.
+func parityKeys[T any](in []T, f func(T) string) []string {
+	out := make([]string, len(in))
+	for i, v := range in {
+		out[i] = f(v)
+	}
+	return out
+}
