+// Fixture-directory coverage, mirroring corpus_test.go's orphan guard: a
+// new mode directory fails here until a TestCorpusParity_* runner is wired
+// for it. "invalid" is excluded by design — its fixtures are rejected
+// before either seam computes anything, so there is nothing to
+// parity-assert.
+func TestCorpusParity_NoOrphanModeDirs(t *testing.T) {
+	executed := []string{"baseline_only", "decompose", "house", "house_policy"}
+	entries, err := os.ReadDir(parityCorpusRoot)
+	if err != nil {
