+	}
+	var got []string
+	for _, e := range entries {
+		if e.IsDir() && e.Name() != "invalid" {
+			got = append(got, e.Name())
+		}
+	}
+	slices.Sort(got)
+	if !slices.Equal(got, executed) {
+		t.Fatalf("corpus mode dirs %v != parity-executed dirs %v — wire a TestCorpusParity_* runner for the new directory", got, executed)
+	}
