+// --- inline parity cases for surfaces the corpus does not carry --------------
+//
+// The corpus fixtures never populate overrides, explicit bitemporal
+// coordinates, or venue-qualified reference data (corpus gaps go back to
+// the corpus issue), so these hand-built requests close the mapping
+// coverage without adding fixtures.
+
+// runInlineParity runs one request through both seams and reports every
+// drift, returning the facade result for non-vacuousness guards.
+func runInlineParity(t *testing.T, c *Client, calc *sdkcore.Calculator, req CalculationRequest) CalculationResult {
+	t.Helper()
+	sdkRes, err := c.Calculate(context.Background(), req)
+	if err != nil {
+		t.Fatalf("SDK Calculate: %v", err)
+	}
+	coreRes, err := calc.Calculate(context.Background(), directInput(t, req, fixedNow))
+	if err != nil {
+		t.Fatalf("sdkcore Calculate: %v", err)
+	}
+	for _, d := range parityDrift(sdkRes, coreRes) {
+		t.Errorf("%s", d)
+	}
+	return sdkRes
+}
