+// parityDrift compares the two seams' results and returns one message per
+// divergent field. It is the single comparison used by both assertParity
+// and the drift canary, so the canary proves this exact logic — not a
+// parallel assertion — detects drift.
+//
+// AuditStatus is deliberately excluded from parity: with no configured
+// sink the facade overrides the result to AuditDropped (client.go) while
+// bare sdkcore reports the internal NoSink's AuditOK — a known,
+// intentional divergence.
+func parityDrift(sdkRes CalculationResult, coreRes sdkcore.Result) []string {
+	var drift []string
+	driftf := func(format string, args ...any) {
+		drift = append(drift, fmt.Sprintf(format, args...))
+	}
+
+	if sdkRes.TraceID != coreRes.TraceID {
+		driftf("TraceID drift: sdk=%q core=%q", sdkRes.TraceID, coreRes.TraceID)
+	}
+	// Bit-equality: exact, and unlike != it reports NaN-vs-NaN as parity
+	// rather than as drift.
+	exact := func(a, b float64) bool { return math.Float64bits(a) == math.Float64bits(b) }
+	if sdkRes.Complete != coreRes.Complete {
+		driftf("Complete drift: sdk=%v core=%v", sdkRes.Complete, coreRes.Complete)
+	}
+
+	// The full snapshot mapping (fromSnapshot): identity, coordinates,
+	// market values, bookkeeping, totals, ratios, deposit requirements.
+	s, cs := sdkRes.Snapshot, coreRes.Snapshot
+	for _, f := range []struct{ name, sdk, core string }{
+		{"AccountID", s.AccountID, cs.AccountID},
+		{"AccountType", string(s.AccountType), string(cs.AccountType)},
+		{"Phase", string(s.Phase), string(cs.Phase)},
+		{"Currency", s.Currency, cs.Currency},
+		{"StockLeverage", fmtRatio(s.StockLeverage), fmtRatio(cs.StockLeverage)},
+		{"GrossLeverage", fmtRatio(s.GrossLeverage), fmtRatio(cs.GrossLeverage)},
+		{"EquityRatio", fmtRatio(s.EquityRatio), fmtRatio(cs.EquityRatio)},
+	} {
+		if f.sdk != f.core {
+			driftf("Snapshot.%s drift: sdk=%q core=%q", f.name, f.sdk, f.core)
+		}
+	}
+	for _, f := range []struct {
+		name      string
+		sdk, core float64
+	}{
+		{"LMVStock", s.LMVStock, cs.LMVStock},
+		{"LMVOption", s.LMVOption, cs.LMVOption},
+		{"SMVStock", s.SMVStock, cs.SMVStock},
+		{"SMVOption", s.SMVOption, cs.SMVOption},
+		{"NetMV", s.NetMV, cs.NetMV},
+		{"GrossExposure", s.GrossExposure, cs.GrossExposure},
+		{"SODEquity", s.SODEquity, cs.SODEquity},
+		{"CashBalance", s.CashBalance, cs.CashBalance},
+		{"PnL", s.PnL, cs.PnL},
+		{"DepositsWithdrawals", s.DepositsWithdrawals, cs.DepositsWithdrawals},
+		{"CurrentEquity", s.CurrentEquity, cs.CurrentEquity},
+		{"AdjustedBalance", s.AdjustedBalance, cs.AdjustedBalance},
+		{"TotalRequirement", s.TotalRequirement, cs.TotalRequirement},
+		{"TotalCashCall", s.TotalCashCall, cs.TotalCashCall},
+	} {
+		if !exact(f.sdk, f.core) {
+			driftf("Snapshot.%s drift: sdk=%g core=%g", f.name, f.sdk, f.core)
+		}
+	}
+	if !s.AsOf.Equal(cs.AsOf) {
+		driftf("Snapshot.AsOf drift: sdk=%v core=%v", s.AsOf, cs.AsOf)
+	}
+	if !maps.Equal(s.DepositRequirements, cs.DepositRequirements) {
+		driftf("Snapshot.DepositRequirements drift: sdk=%v core=%v", s.DepositRequirements, cs.DepositRequirements)
+	}
+
+	// The full trace mapping (fromTrace): every seal and hash, plus the
+	// version and bitemporal fields. On modes where a seal does not apply
+	// both sides are empty, so the comparison stays exact.
+	for _, f := range []struct{ name, sdk, core string }{
+		{"EngineVersion", sdkRes.Trace.EngineVersion, coreRes.Trace.EngineVersion},
+		{"RulebookSHA", sdkRes.Trace.RulebookSHA, coreRes.Trace.RulebookSHA},
+		{"OverlayRulebookHash", sdkRes.Trace.OverlayRulebookHash, coreRes.Trace.OverlayRulebookHash},
+		{"PositionsSHA", sdkRes.Trace.PositionsSHA, coreRes.Trace.PositionsSHA},
+		{"PolicySHA", sdkRes.Trace.PolicySHA, coreRes.Trace.PolicySHA},
+		{"RefdataSHA", sdkRes.Trace.RefdataSHA, coreRes.Trace.RefdataSHA},
+		{"OverridesSHA", sdkRes.Trace.OverridesSHA, coreRes.Trace.OverridesSHA},
+	} {
+		if f.sdk != f.core {
+			driftf("Trace.%s drift: sdk=%q core=%q", f.name, f.sdk, f.core)
+		}
+	}
+	for _, f := range []struct {
+		name      string
+		sdk, core time.Time
+	}{
+		{"EvaluatedAt", sdkRes.Trace.EvaluatedAt, coreRes.Trace.EvaluatedAt},
+		{"AsOf", sdkRes.Trace.AsOf, coreRes.Trace.AsOf},
+		{"TxnCutoff", sdkRes.Trace.TxnCutoff, coreRes.Trace.TxnCutoff},
+	} {
+		if !f.sdk.Equal(f.core) {
+			driftf("Trace.%s drift: sdk=%v core=%v", f.name, f.sdk, f.core)
+		}
+	}
+	if got, want := parityKeys(sdkRes.Trace.AppliedOverrides, overrideKey), parityKeys(coreRes.Trace.AppliedOverrides, coreOverrideKey); !slices.Equal(got, want) {
+		driftf("Trace.AppliedOverrides drift: sdk=%v core=%v", got, want)
+	}
+
+	// Per-position collections and warnings: pins the facade's result
+	// mapping (fromPositionEvaluations, fromExclusions), not just totals.
+	for _, coll := range []struct {
+		name      string
+		sdk, core []string
+	}{
+		{"Evaluations", parityKeys(sdkRes.Snapshot.Evaluations, outcomeKey), parityKeys(coreRes.Snapshot.Evaluations, coreOutcomeKey)},
+		{"Violations", parityKeys(sdkRes.Snapshot.Violations, outcomeKey), parityKeys(coreRes.Snapshot.Violations, coreOutcomeKey)},
+		{"Errors", parityKeys(sdkRes.Snapshot.Errors, outcomeKey), parityKeys(coreRes.Snapshot.Errors, coreOutcomeKey)},
+		{"Exclusions", parityKeys(sdkRes.Exclusions, exclusionKey), parityKeys(coreRes.Snapshot.Exclusions, coreExclusionKey)},
+		{"Warnings", sdkRes.Snapshot.Warnings, coreRes.Snapshot.Warnings},
+	} {
+		if !slices.Equal(coll.sdk, coll.core) {
+			driftf("%s drift: sdk=%v core=%v", coll.name, coll.sdk, coll.core)
+		}
+	}
+
+	// House block: presence and the full mapped content must agree.
+	switch sdkHouse, coreHouse := sdkRes.House, coreRes.House; {
+	case (sdkHouse == nil) != (coreHouse == nil):
+		driftf("House presence drift: sdk=%v core=%v", sdkHouse != nil, coreHouse != nil)
+	case sdkHouse != nil:
+		for _, num := range []struct {
+			name      string
+			sdk, core float64
+		}{
+			{"BaselineRequirement", sdkHouse.BaselineRequirement, coreHouse.BaselineRequirement},
+			{"BaselineCashCall", sdkHouse.BaselineCashCall, coreHouse.BaselineCashCall},
+			{"HouseRequirement", sdkHouse.HouseRequirement, coreHouse.HouseRequirement},
+			{"HouseCashCall", sdkHouse.HouseCashCall, coreHouse.HouseCashCall},
+			{"Excess", sdkHouse.Excess, coreHouse.Excess},
+		} {
+			if !exact(num.sdk, num.core) {
+				driftf("House.%s drift: sdk=%g core=%g", num.name, num.sdk, num.core)
+			}
+		}
+		for _, coll := range []struct {
+			name      string
+			sdk, core []string
+		}{
+			{"Components", parityKeys(sdkHouse.Components, houseComponentKey), parityKeys(coreHouse.Components, coreHouseComponentKey)},
+			{"Violations", parityKeys(sdkHouse.Violations, houseViolationKey), parityKeys(coreHouse.Violations, coreHouseViolationKey)},
+			{"Warnings", sdkHouse.Warnings, coreHouse.Warnings},
+		} {
+			if !slices.Equal(coll.sdk, coll.core) {
+				driftf("House.%s drift: sdk=%v core=%v", coll.name, coll.sdk, coll.core)
+			}
+		}
+	}
+
+	// Decompose path: the per-position sequences must match in full —
+	// identity, sub-positions with slots and scored results, attribution,
+	// and residual errors (fromDecompositions). Per-position trace IDs
+	// fold in EvaluatedAt, so the shared fixed clock is what makes this
+	// comparable.
+	if got, want := parityKeys(sdkRes.Decompositions, decompositionKey), parityKeys(coreRes.Decompositions, coreDecompositionKey); !slices.Equal(got, want) {
+		driftf("decomposition drift: sdk=%v core=%v", got, want)
+	}
+
+	return drift
+}
+
+func assertParity(t *testing.T, c *Client, calc *sdkcore.Calculator, fx parityFixture) {
+	t.Helper()
+	ctx := context.Background()
+
+	sdkRes, err := c.Calculate(ctx, fx.req)
+	if err != nil {
+		t.Fatalf("%s: SDK Calculate: %v", fx.path, err)
+	}
+	coreRes, err := calc.Calculate(ctx, directInput(t, fx.req, fixedNow))
+	if err != nil {
+		t.Fatalf("%s: sdkcore Calculate: %v", fx.path, err)
+	}
+
+	for _, d := range parityDrift(sdkRes, coreRes) {
+		t.Errorf("%s: %s", fx.path, d)
+	}
+
+	// Non-vacuousness guards: equal-because-both-dropped is not parity.
+	if !fx.req.Snapshot.Policy.IsZero() && sdkRes.Trace.PolicySHA == "" {
+		t.Errorf("%s: fixture carries policy but PolicySHA is empty on both paths", fx.path)
+	}
+	if mode := fx.req.Mode; mode == ModeHouse || mode == "" {
+		// House mode always seals refdata — an empty refdata set still
+		// hashes to a value (pins ReferenceData normalization through the
+		// mapping layer).
+		if sdkRes.Trace.RefdataSHA == "" {
+			t.Errorf("%s: house fixture but RefdataSHA is empty on both paths", fx.path)
+		}
+	}
+	if fx.req.Decompose && len(sdkRes.Decompositions) == 0 {
+		t.Errorf("%s: decompose fixture produced no decompositions — the pair comparison is vacuous", fx.path)
+	}
+}
