+// Corpus-driven parity suite (D5, host-snapshot-conformance): every valid
+// corpus fixture runs through both seams — the public facade
+// (Client.Calculate) and a directly-constructed sdkcore.Input — and fails
+// on any divergence in TraceID, TotalRequirement, Complete, or the
+// integrity seals.
+//
+// Path B constructs the internal input independently of the facade's
+// production mappers (see the fixture* helpers below), so mapper drift
+// cannot cancel out across the two paths.
+//
+// Unlike corpus_test.go this file is in package limen (not limen_test) so
+// it can reach package-private test collaborators (noOverridesStore, the
+// fixed clock, mustRulebook). That means it cannot import
+// internal/hostfixtures (which imports pkg/limen — an in-package test
+// would form an import cycle), so it carries its own minimal request-only
+// loader; fixture strictness and expectation validation stay with the
+// hostfixtures loader exercised by corpus_test.go.
+package limen
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"maps"
+	"math"
+	"os"
+	"path/filepath"
+	"slices"
+	"strings"
+	"testing"
+	"time"
+
+	"limen/internal/account"
+	"limen/internal/engine"
+	"limen/internal/overlay"
+	"limen/internal/sdkcore"
+)
+
+const parityCorpusRoot = "../../testdata/hostsnapshots"
+
+type parityFixture struct {
+	name string // filename without the .json extension
+	path string
+	req  CalculationRequest
+}
+
+// loadParityFixtures reads every fixture request in one corpus mode
+// directory. An empty directory fails: it would silently assert nothing.
+func loadParityFixtures(t *testing.T, mode string) []parityFixture {
+	t.Helper()
+	dir := filepath.Join(parityCorpusRoot, mode)
+	entries, err := os.ReadDir(dir)
+	if err != nil {
+		t.Fatalf("read corpus dir: %v", err)
+	}
+	var out []parityFixture
+	for _, e := range entries {
+		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
+			continue
+		}
+		path := filepath.Join(dir, e.Name())
+		data, err := os.ReadFile(path)
+		if err != nil {
+			t.Fatalf("read fixture: %v", err)
+		}
+		var doc struct {
+			Request CalculationRequest `json:"request"`
+		}
+		if err := json.Unmarshal(data, &doc); err != nil {
+			t.Fatalf("%s: %v", path, err)
+		}
+		out = append(out, parityFixture{
+			name: strings.TrimSuffix(e.Name(), ".json"),
+			path: path,
+			req:  doc.Request,
+		})
+	}
+	if len(out) == 0 {
+		t.Fatalf("no fixtures in %s", dir)
+	}
+	return out
+}
+
+// parityClient builds Path A: a public Client with the fixed clock.
+func parityClient(t *testing.T, opts Options) *Client {
+	t.Helper()
+	opts.Clock = fixedClock
+	c, err := New(opts)
+	if err != nil {
+		t.Fatalf("New: %v", err)
+	}
+	return c
+}
+
+// parityCalculator builds Path B: a bare sdkcore.Calculator wired with the
+// same rulebook, clock, and — when overlay paths are given — the same
+// overlay rulebook and the empty override set the facade's NoOverrides
+// declaration resolves to.
+func parityCalculator(t *testing.T, overlayPaths ...string) *sdkcore.Calculator {
+	t.Helper()
+	return parityCalculatorWithStore(t, noOverridesStore{}, overlayPaths...)
+}
+
+// parityCalculatorWithStore is parityCalculator with an explicit internal
+// override store, for parity cases that exercise a populated override set.
+func parityCalculatorWithStore(t *testing.T, store overlay.OverrideStore, overlayPaths ...string) *sdkcore.Calculator {
+	t.Helper()
+	deps := sdkcore.Dependencies{Rulebook: mustRulebook(t), Clock: fixedClock}
+	if len(overlayPaths) > 0 {
+		docs := make([][]byte, len(overlayPaths))
+		for i, p := range overlayPaths {
+			data, err := os.ReadFile(p)
+			if err != nil {
+				t.Fatalf("read overlay: %v", err)
+			}
+			docs[i] = data
+		}
+		ov, err := overlay.ParseRulebook(docs...)
+		if err != nil {
+			t.Fatalf("overlay.ParseRulebook: %v", err)
+		}
+		deps.Overlay = ov
+		deps.Overrides = store
+	}
+	calc, err := sdkcore.New(deps)
+	if err != nil {
+		t.Fatalf("sdkcore.New: %v", err)
+	}
+	return calc
+}
+
+// staticOverrideStore is Path B's independent counterpart to a facade
+// OverrideResolver: it hands the pipeline a fixed internal override set,
+// built without going through toOverride.
+type staticOverrideStore struct {
+	noOverridesStore
+	rows []overlay.Override
+}
+
+func (s staticOverrideStore) Resolve(context.Context, overlay.ResolveQuery) ([]overlay.Override, error) {
+	return s.rows, nil
+}
+
+// --- independent fixture→internal construction ------------------------------
+//
+// Path B builds the internal input types straight from the public snapshot
+// WITHOUT calling the facade's production mappers (toAccount,
+// toReferenceData, toPolicyFacts). The duplication is the point: two
+// independent constructions must agree, so a field dropped or miscopied by
+// a facade mapper surfaces as parity drift (seals, totals, TraceID)
+// instead of cancelling out on both paths (PR #297 review).
+
+func fixtureLegs(in []Leg) []engine.Leg {
+	out := make([]engine.Leg, len(in))
+	for i, l := range in {
+		out[i] = engine.Leg{
+			Side:                   engine.Side(l.Side),
+			Kind:                   engine.Kind(l.Kind),
+			OptionType:             l.OptionType,
+			K:                      l.K,
+			P:                      l.P,
+			P0:                     l.P0,
+			Qty:                    l.Qty,
+			Mult:                   l.Mult,
+			Style:                  l.Style,
+			Venue:                  l.Venue,
+			SettleStyle:            l.SettleStyle,
+			Expiration:             l.Expiration,
+			Underlying:             l.Underlying,
+			TimeToExpirationMonths: l.TimeToExpirationMonths,
+			BrokerGuaranteed:       l.BrokerGuaranteed,
+			Shares:                 l.Shares,
+			ShortSaleProceeds:      l.ShortSaleProceeds,
+			SalePrice:              l.SalePrice,
+			Price:                  l.Price,
+			TracksIndex:            l.TracksIndex,
+			Leveraged:              l.Leveraged,
+			TrackingRatio:          l.TrackingRatio,
+			KEquivalent:            l.KEquivalent,
+		}
+	}
+	return out
+}
+
+func fixtureAccount(snap CalculationSnapshot, asOf time.Time) account.Account {
+	acctType := snap.Account.Type
+	if acctType == "" {
+		acctType = MarginAccount
+	}
+	phase := snap.Account.Phase
+	if phase == "" {
+		phase = Initial
+	}
+	positions := make([]account.AccountPosition, len(snap.Positions))
+	for i, p := range snap.Positions {
+		positions[i] = account.AccountPosition{
+			ID: p.ID,
+			Position: engine.Position{
+				Legs:                    fixtureLegs(p.Legs),
+				U:                       p.U,
+				Class:                   p.Class,
+				Lev:                     p.Lev,
+				UnderlyingIsEquityBased: p.UnderlyingIsEquityBased,
+			},
+		}
+	}
+	return account.Account{
+		ID:                  snap.Account.ID,
+		AccountType:         engine.AccountType(acctType),
+		Phase:               engine.Phase(phase),
+		AsOf:                asOf,
+		Currency:            snap.Account.Currency,
+		SODEquity:           snap.Bookkeeping.SODEquity,
+		CashBalance:         snap.Bookkeeping.CashBalance,
+		PnL:                 snap.Bookkeeping.PnL,
+		DepositsWithdrawals: snap.Bookkeeping.DepositsWithdrawals,
+		Positions:           positions,
+	}
+}
+
+func fixtureRefdata(rows []SecurityFacts) overlay.ReferenceData {
+	if len(rows) == 0 {
+		return overlay.ReferenceData{}
+	}
+	secs := make(map[overlay.SecKey]overlay.SecurityFacts, len(rows))
+	for _, r := range rows {
+		secs[overlay.SecKey{Symbol: r.Symbol, Venue: r.Venue}] = overlay.SecurityFacts{
+			Symbol:          r.Symbol,
+			Venue:           r.Venue,
+			InstrumentKind:  r.InstrumentKind,
+			Underlying:      r.Underlying,
+			IssuerID:        r.IssuerID,
+			Sector:          r.Sector,
+			Industry:        r.Industry,
+			GICSSubIndustry: r.GICSSubIndustry,
+
+			LastPrice:         r.LastPrice,
+			ADV20:             r.ADV20,
+			MedianVolume20:    r.MedianVolume20,
+			MarketCap:         r.MarketCap,
+			SharesOutstanding: r.SharesOutstanding,
+
+			Volatility30D:   r.Volatility30D,
+			HardToBorrow:    r.HardToBorrow,
+			BorrowRate:      r.BorrowRate,
+			Marginable:      r.Marginable,
+			LeveragedFactor: r.LeveragedFactor,
+		}
+	}
+	return overlay.ReferenceData{Securities: secs}
+}
+
+func fixturePolicyFacts(p PolicyContext) overlay.PolicyFacts {
+	out := overlay.PolicyFacts{
+		RiskProfile:  p.RiskProfile,
+		AccountGroup: p.AccountGroup,
+		HouseProfile: p.HouseProfile,
+	}
+	if len(p.Attributes) > 0 {
+		out.Attributes = make(map[string]any, len(p.Attributes))
+		for k, v := range p.Attributes {
+			switch v.Kind {
+			case PolicyString:
+				out.Attributes[k] = v.String
+			case PolicyNumber:
+				out.Attributes[k] = v.Number
+			case PolicyBool:
+				out.Attributes[k] = v.Bool
+			}
+		}
+	}
+	if len(p.PendingCash) > 0 {
+		agg := map[string]float64{}
+		for _, m := range p.PendingCash {
+			agg[m.Direction+"_"+m.Type+"_"+m.Status] += m.Amount
+			switch m.Direction {
+			case CashInbound:
+				agg["inbound_total"] += m.Amount
+				agg["net"] += m.Amount
+			case CashOutbound:
+				agg["outbound_total"] += m.Amount
+				agg["net"] -= m.Amount
+			}
+		}
+		out.PendingAggregates = agg
+	}
+	return out
+}
+
+// directInput replicates Client.buildInput's orchestration — mode
+// defaulting, decompose flag, single-sample clock-defaulting of the
+// bitemporal coordinates — over the independent fixture constructions
+// above. Shared by the corpus suite, the drift canary, and
+// TestMappingParity_SDKMatchesSdkcoreDirect.
+func directInput(t *testing.T, req CalculationRequest, now time.Time) sdkcore.Input {
+	t.Helper()
+	mode := req.Mode
+	if mode == "" {
+		mode = ModeHouse
+	}
+	asOf, txnCutoff := req.Snapshot.AsOf, req.Snapshot.TxnCutoff
+	if asOf.IsZero() {
+		asOf = now
+	}
+	if txnCutoff.IsZero() {
+		txnCutoff = now
+	}
+	return sdkcore.Input{
+		Account:           fixtureAccount(req.Snapshot, asOf),
+		Refdata:           fixtureRefdata(req.Snapshot.Refdata),
+		Policy:            fixturePolicyFacts(req.Snapshot.Policy),
+		AsOf:              asOf,
+		TxnCutoff:         txnCutoff,
+		ApplyHouseOverlay: mode == ModeHouse,
+		Decompose:         req.Decompose,
+	}
+}
