+// --- inline parity cases for surfaces the corpus does not carry --------------
+//
+// The corpus fixtures never populate overrides, explicit bitemporal
+// coordinates, or venue-qualified reference data (corpus gaps go back to
+// the corpus issue), so these hand-built requests close the mapping
+// coverage without adding fixtures.
+
+// runInlineParity runs one request through both seams and reports every
+// drift, returning the facade result for non-vacuousness guards.
+func runInlineParity(t *testing.T, c *Client, calc *sdkcore.Calculator, req CalculationRequest) CalculationResult {
+	t.Helper()
+	sdkRes, err := c.Calculate(context.Background(), req)
+	if err != nil {
+		t.Fatalf("SDK Calculate: %v", err)
+	}
+	coreRes, err := calc.Calculate(context.Background(), directInput(t, req, fixedNow))
+	if err != nil {
+		t.Fatalf("sdkcore Calculate: %v", err)
+	}
+	for _, d := range parityDrift(sdkRes, coreRes) {
+		t.Errorf("%s", d)
+	}
+	return sdkRes
+}
+
+// A populated override set: the facade resolver returns two fully-populated
+// public Overrides (mapped through toOverride) — one amount-based with a
+// bounded validity window, one pct-based (Pct and Amount are mutually
+// exclusive per row) — while Path B's store returns the equivalent internal
+// overrides built independently. Pins fromOverride / toOverride and the
+// AppliedOverrides trace mapping with every field carrying real content.
+// The request also carries explicit, distinct bitemporal coordinates and
+// the test asserts the resolver receives exactly those — a resolverStore
+// that swapped or clock-stamped them would fail here even though both
+// seams' seals would still agree.
+func TestCorpusParity_ActiveOverrides(t *testing.T) {
+	var (
+		asOf      = fixedNow.Add(-48 * time.Hour)
+		txnCutoff = fixedNow.Add(-47 * time.Hour)
+		validFrom = fixedNow.Add(-30 * 24 * time.Hour)
+		validTo   = fixedNow.Add(365 * 24 * time.Hour)
+		// TxnTime differs from ValidFrom on every row so a mapper swapping
+		// the business-valid and transaction coordinates drifts the seal.
+		txnTime = fixedNow.Add(-29 * 24 * time.Hour)
+	)
+	publicRows := []Override{
+		{
+			ID: "ovr-1", Scope: "symbol", Key: "XYZ",
+			Mode: "max", Basis: "market_value", Amount: 12000,
+			Priority: 7, Reason: "concentration cap",
+			ValidFrom: validFrom, ValidTo: validTo, TxnTime: txnTime, Version: 3,
+		},
+		{
+			ID: "ovr-2", Scope: "symbol", Key: "XYZ",
+			Mode: "floor", Basis: "market_value", Pct: 0.4,
+			Priority: 8, Reason: "house floor",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 1,
+		},
+		{
+			ID: "ovr-3", Scope: "account", Key: "ACC-1",
+			Mode: "add", Basis: "account_equity", Amount: 500,
+			Priority: 9, Reason: "account surcharge",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 2,
+		},
+		{
+			ID: "ovr-4", Scope: "group", Key: "tech",
+			Mode: "max", Basis: "group_gross_mv", Pct: 0.25,
+			Priority: 10, Reason: "sector cap",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 1,
+		},
+	}
+	var gotAsOf, gotTxnCutoff time.Time
+	c, err := New(Options{
+		Rules:   RulesFile(rulesPath),
+		Overlay: OverlayFiles(overlayPath),
+		Overrides: resolverFunc(func(_ context.Context, asOf, txnCutoff time.Time) ([]Override, error) {
+			gotAsOf, gotTxnCutoff = asOf, txnCutoff
+			return publicRows, nil
+		}),
+		Clock: fixedClock,
+	})
+	if err != nil {
+		t.Fatalf("New: %v", err)
+	}
+	store := staticOverrideStore{rows: []overlay.Override{
+		{
+			ID: "ovr-1", Scope: overlay.ScopeSymbol, Key: "XYZ",
+			Mode: "max", Basis: "market_value", Amount: 12000,
+			Priority: 7, Reason: "concentration cap",
+			ValidFrom: validFrom, ValidTo: validTo, TxnTime: txnTime, Version: 3,
+		},
+		{
+			ID: "ovr-2", Scope: overlay.ScopeSymbol, Key: "XYZ",
+			Mode: "floor", Basis: "market_value", Pct: 0.4,
+			Priority: 8, Reason: "house floor",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 1,
+		},
+		{
+			ID: "ovr-3", Scope: overlay.ScopeAccount, Key: "ACC-1",
+			Mode: "add", Basis: "account_equity", Amount: 500,
+			Priority: 9, Reason: "account surcharge",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 2,
+		},
+		{
+			ID: "ovr-4", Scope: overlay.ScopeGroup, Key: "tech",
+			Mode: "max", Basis: "group_gross_mv", Pct: 0.25,
+			Priority: 10, Reason: "sector cap",
+			ValidFrom: validFrom, TxnTime: txnTime, Version: 1,
+		},
+	}}
+	calc := parityCalculatorWithStore(t, store, overlayPath)
+
+	req := coveredCallRequest(ModeHouse)
+	req.Snapshot.AsOf = asOf
+	req.Snapshot.TxnCutoff = txnCutoff
+
+	sdkRes := runInlineParity(t, c, calc, req)
+	// The resolver must see the caller's coordinates, unswapped and
+	// un-clock-stamped.
+	if !gotAsOf.Equal(asOf) || !gotTxnCutoff.Equal(txnCutoff) {
+		t.Fatalf("resolver coordinates = (%v, %v), want the caller-supplied (%v, %v)",
+			gotAsOf, gotTxnCutoff, asOf, txnCutoff)
+	}
+	// Non-vacuous: all four overrides (symbol, account, and group scopes)
