+// Corpus-driven parity suite (D5, host-snapshot-conformance): every valid
+// corpus fixture runs through both seams — the public facade
+// (Client.Calculate) and a directly-constructed sdkcore.Input — and fails
+// on any divergence in TraceID, TotalRequirement, Complete, or the
+// integrity seals.
+//
+// Path B constructs the internal input independently of the facade's
+// production mappers (see the fixture* helpers below), so mapper drift
+// cannot cancel out across the two paths.
+//
+// Unlike corpus_test.go this file is in package limen (not limen_test) so
+// it can reach package-private test collaborators (noOverridesStore, the
+// fixed clock, mustRulebook). That means it cannot import
+// internal/hostfixtures (which imports pkg/limen — an in-package test
+// would form an import cycle), so it carries its own minimal request-only
+// loader; fixture strictness and expectation validation stay with the
+// hostfixtures loader exercised by corpus_test.go.
+package limen
+
+import (
+	"context"
+	"encoding/json"
+	"os"
+	"path/filepath"
+	"slices"
+	"strings"
+	"testing"
+	"time"
+
+	"limen/internal/account"
+	"limen/internal/engine"
+	"limen/internal/overlay"
+	"limen/internal/sdkcore"
+)
+
+const parityCorpusRoot = "../../testdata/hostsnapshots"
+
+type parityFixture struct {
+	name string // filename without the .json extension
+	path string
+	req  CalculationRequest
+}
+
+// loadParityFixtures reads every fixture request in one corpus mode
+// directory. An empty directory fails: it would silently assert nothing.
+func loadParityFixtures(t *testing.T, mode string) []parityFixture {
+	t.Helper()
+	dir := filepath.Join(parityCorpusRoot, mode)
+	entries, err := os.ReadDir(dir)
+	if err != nil {
+		t.Fatalf("read corpus dir: %v", err)
+	}
+	var out []parityFixture
+	for _, e := range entries {
+		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
+			continue
+		}
+		path := filepath.Join(dir, e.Name())
+		data, err := os.ReadFile(path)
+		if err != nil {
+			t.Fatalf("read fixture: %v", err)
+		}
+		var doc struct {
+			Request CalculationRequest `json:"request"`
+		}
+		if err := json.Unmarshal(data, &doc); err != nil {
+			t.Fatalf("%s: %v", path, err)
+		}
+		out = append(out, parityFixture{
+			name: strings.TrimSuffix(e.Name(), ".json"),
+			path: path,
+			req:  doc.Request,
+		})
+	}
+	if len(out) == 0 {
+		t.Fatalf("no fixtures in %s", dir)
+	}
+	return out
+}
+
+// parityClient builds Path A: a public Client with the fixed clock.
+func parityClient(t *testing.T, opts Options) *Client {
+	t.Helper()
+	opts.Clock = fixedClock
+	c, err := New(opts)
+	if err != nil {
+		t.Fatalf("New: %v", err)
+	}
+	return c
+}
+
+// parityCalculator builds Path B: a bare sdkcore.Calculator wired with the
+// same rulebook, clock, and — when overlay paths are given — the same
+// overlay rulebook and the empty override set the facade's NoOverrides
+// declaration resolves to.
+func parityCalculator(t *testing.T, overlayPaths ...string) *sdkcore.Calculator {
+	t.Helper()
+	return parityCalculatorWithStore(t, noOverridesStore{}, overlayPaths...)
+}
+
+// parityCalculatorWithStore is parityCalculator with an explicit internal
+// override store, for parity cases that exercise a populated override set.
+func parityCalculatorWithStore(t *testing.T, store overlay.OverrideStore, overlayPaths ...string) *sdkcore.Calculator {
+	t.Helper()
+	deps := sdkcore.Dependencies{Rulebook: mustRulebook(t), Clock: fixedClock}
+	if len(overlayPaths) > 0 {
+		docs := make([][]byte, len(overlayPaths))
+		for i, p := range overlayPaths {
+			data, err := os.ReadFile(p)
+			if err != nil {
+				t.Fatalf("read overlay: %v", err)
+			}
+			docs[i] = data
+		}
+		ov, err := overlay.ParseRulebook(docs...)
+		if err != nil {
+			t.Fatalf("overlay.ParseRulebook: %v", err)
+		}
+		deps.Overlay = ov
+		deps.Overrides = store
+	}
+	calc, err := sdkcore.New(deps)
+	if err != nil {
+		t.Fatalf("sdkcore.New: %v", err)
+	}
+	return calc
+}
+
+// staticOverrideStore is Path B's independent counterpart to a facade
