+import (
+	"encoding/json"
+	"testing"
+)
+
+// Money contract: every monetary field on a Result is cent-exact. These
+// fixtures are lifted verbatim from the 2026-09-07 regression report, where
+// float64 formula arithmetic surfaced 449.99999999999955 for $450.00,
+// 1760.0000000000002 for $1,760.00, and 2300.0000000000005 for $2,300.00.
+// Equality is exact on purpose — assertClose's 0.01 tolerance would have
+// passed the drifting values too — and the JSON spelling is checked because
+// the wire form is what hosts compare against.
+
+func indexLeg(side Side, optType string, k, p, qty float64) Leg {
+	return Leg{
+		Side: side, Kind: OptionKind, OptionType: optType,
+		K: k, P: p, P0: p, Qty: qty, Mult: 100,
+		Style: "european", Venue: "listed", SettleStyle: "cash",
+		Expiration: "2021-11-19", Underlying: "SYNTH_INDEX",
+		TimeToExpirationMonths: 1.6,
+	}
+}
+
+func assertCents(t *testing.T, label string, got, want float64) {
+	t.Helper()
+	if got != want {
+		t.Errorf("%s: got %v, want exactly %v", label, got, want)
+	}
+}
+
+func TestMoneyPrecision_europeanLongBoxInitialFunding(t *testing.T) {
+	rb := loadRB(t)
+	pos := Position{
+		U: 550, Class: "broad_based_index", Lev: 1, UnderlyingIsEquityBased: true,
+		Legs: []Leg{
+			indexLeg(Long, "call", 535, 19.4, 1),
+			indexLeg(Short, "call", 545, 12.2, 1),
+			indexLeg(Long, "put", 545, 5.3, 1),
+			indexLeg(Short, "put", 535, 3, 1),
+		},
+	}
+	// Plain Evaluate, not mustEvaluate: the European long box is also a
+	// limited-risk combo by shape, and first-match order (not uniqueness)
+	// is what selects the loan-value rule — the same pre-existing dispatch
+	// TestLongBoxEuropeanMargin_loanValue relies on.
+	res, err := rb.Evaluate(pos, MarginAccount, Initial)
+	if err != nil {
+		t.Fatalf("Evaluate: %v", err)
+	}
+	if res.RuleID != "long_box_spread_european" {
+		t.Fatalf("matched %s, want long_box_spread_european", res.RuleID)
+	}
+	assertCents(t, "requirement", res.Requirement, 500)
+	if res.InitialFunding == nil {
+		t.Fatal("initial funding must be modeled for the European long box")
+	}
+	assertCents(t, "initial_funding", *res.InitialFunding, 450) // was 449.99999999999955
+
+	b, err := json.Marshal(res)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if want := `"initial_funding":450`; !contains(string(b), want) {
+		t.Errorf("JSON must carry %s, got %s", want, b)
+	}
+}
+
+func TestMoneyPrecision_callButterflyProceedsAndFunding(t *testing.T) {
+	rb := loadRB(t)
+	pos := Position{
+		U: 550, Class: "broad_based_index", Lev: 1, UnderlyingIsEquityBased: true,
+		Legs: []Leg{
+			indexLeg(Long, "call", 545, 12.4, 1),
+			indexLeg(Short, "call", 550, 8.8, 2),
+			indexLeg(Long, "call", 565, 2, 1),
+		},
+	}
+	res := mustEvaluate(t, rb, pos, MarginAccount, Initial)
+	if res.RuleID != "generic_limited_risk_combo" {
+		t.Fatalf("matched %s, want generic_limited_risk_combo", res.RuleID)
+	}
+	assertCents(t, "requirement", res.Requirement, 2440)
+	assertCents(t, "applied_proceeds", res.AppliedProceeds, 1760) // was 1760.0000000000002
+	// The combo rule models no separate loan value, so hosts read the cash
+	// call as the funding figure — that is the 679.9999999999998 the report saw.
