+// BreakdownFormulas declares optional monetary outputs for one account/phase
+// cell. The expressions use the same activation as the requirement formula;
+// they do not change the requirement or read other rounded output fields.
+type BreakdownFormulas struct {
+	LongCost              string `yaml:"long_cost,omitempty"`
+	PayoffLoss            string `yaml:"payoff_loss,omitempty"`
+	LoanValue             string `yaml:"loan_value,omitempty"`
+	NetDebit              string `yaml:"net_debit,omitempty"`
+	ExpiryValue           string `yaml:"expiry_value,omitempty"`
+	EquityValuationCap    string `yaml:"equity_valuation_cap,omitempty"`
+	NakedShortRequirement string `yaml:"naked_short_requirement,omitempty"`
+}
+
+func (b BreakdownFormulas) expressions() map[string]string {
+	expressions := map[string]string{
+		"long_cost": b.LongCost, "payoff_loss": b.PayoffLoss,
+		"loan_value": b.LoanValue, "net_debit": b.NetDebit,
+		"expiry_value": b.ExpiryValue, "equity_valuation_cap": b.EquityValuationCap,
+		"naked_short_requirement": b.NakedShortRequirement,
+	}
+	for name, expr := range expressions {
+		if expr == "" {
+			delete(expressions, name)
+		}
+	}
+	return expressions
+}
